-- New Recruitment › the pachanga zones of the Chronicle board (docs/game/mods/new-recruitment-pachangas.md), script side.
-- Data: every active mod's content\pachangas\*.toml (schema NewRecruitment.pachangas/1; this module's zones.toml is
-- generated by research/scripts/new_recruitment_pachanga_zones.py): [[NewRecruitment.PachangaZone]] (a board node, its
-- title, its Chronicle match, its stadium), [[NewRecruitment.Pachanga]] (a 5v5 friendly of a zone: its rival team, level,
-- format, its players' cards and each one's mini-challenge), [[NewRecruitment.PachangaChallenge]] (the challenge types:
-- check, params, text) and [[NewRecruitment.PachangaTechniqueList]] (technique lists the checks read).
-- While an armed pachanga's match runs, every player's challenge is followed from the VRFW match events (event-driven);
-- at match_end the players whose challenge was met are the result; won / lost and the score are the game's own
-- (VRFW MatchResult.last, signal vrfw.match_result: penalties and forfeits included). Game Lua side:
-- assets\lua\vs_route_town_menu\new_recruitment_pachangas.lua.
-- | Command | Args | Returns |
-- |---|---|---|
-- | CMND_NEWRECRUITMENT_PACHANGA_ZONE | node name | zone index, title text id, stadium map crc, pachanga count (nothing = no zone) |
-- | CMND_NEWRECRUITMENT_PACHANGA_GET | zone index, i (1-based) | key, rival team crc, team name, level, format, challenge, won (bool), card count, cards… |
-- | CMND_NEWRECRUITMENT_PACHANGA_PLAYER | key, i (1-based) | card, challenge type name, its text id, its first param (n or s), met before (bool) |
-- | CMND_NEWRECRUITMENT_PACHANGA_ARM | key | true: the next match is that pachanga's (its challenges are followed) |
-- | CMND_NEWRECRUITMENT_PACHANGA_RESULT | — | key, won (bool), goals for, goals against, level, met count, met cards… of the last armed pachanga's match; nothing = none (read once) |
-- | CMND_NEWRECRUITMENT_PACHANGA_WON | key | true when the pachanga was won in this save slot |
-- | CMND_NEWRECRUITMENT_PACHANGA_SET_WON | key | true (saved: key won.<key>, owner new_recruitment) |
-- | CMND_NEWRECRUITMENT_PACHANGA_SET_MET | card | true (saved: key met.<card>: his challenge was met once) |
-- | CMND_NEWRECRUITMENT_PACHANGA_LINEUP | key | the cards who play its next match (the rotation's lineup, goalkeeper first) |
-- | CMND_NEWRECRUITMENT_PACHANGA_BASE | team level | true: the base the pachangas' levels scale from (the list opens) |
-- | CMND_NEWRECRUITMENT_PACHANGA_LEVEL | key | its level now, the friendly's row level (the members' offsets base) |
-- | CMND_NEWRECRUITMENT_PACHANGA_MENU | zone index, i | the pose row screen's page (VRFW.PoseRow source, docs/framework/pose-row.md §2): i = 0 the header, i >= 1 pachanga i |

NewRecruitment = NewRecruitment or {}
local P = {}

local FOLDER = "content/pachangas"
require "VRFW/lib/basics"
local info, warn = VRFW.logger("pachangas")

local crc = VRFW.crc32

local ZONES = nil      -- { { name, node, title, stadium, pachangas = { … } } … }
local LEVEL = { scale = "data", min = 1, max = 200, row_level = 0 }   -- zones.toml [NewRecruitment.PachangaLevel]
local BASE = nil       -- the player's team level the levels scale from (CMND_NEWRECRUITMENT_PACHANGA_BASE)
local BY_NODE = {}     -- node name -> zone index
local BY_KEY = {}      -- pachanga key -> pachanga
local TYPES = {}       -- challenge type name -> { name, check, params, text }
local LISTS = {}       -- technique list name -> { [skill id] = true }
local LIVE = nil       -- the armed pachanga's match: see arm()
local PLAYED = nil     -- { key, gf, ga, won, met = { card … }, judged } until read

local function id_of(text)
  if type(text) == "number" then return math.floor(text) % 4294967296 end
  if type(text) ~= "string" then return nil end
  local h = text:match("^%s*0[xX](%x+)%s*$")
  return h and tonumber(h, 16) or nil
end

local function load_zones()
  if ZONES ~= nil then return ZONES end
  ZONES = {}
  local ok, files = pcall(VRFW.files.declarations, FOLDER)
  if not ok then
    warn("the pachanga zones could not be read (" .. tostring(files) .. "): none")
    return ZONES
  end
  local by_zone, pending = {}, {}
  for _, file in ipairs(type(files) == "table" and files or {}) do
    local root = type(file.data) == "table" and file.data.NewRecruitment or nil
    if type(root) == "table" then
      for _, t in ipairs(root.PachangaChallenge or {}) do
        if type(t.name) == "string" and type(t.check) == "string" then
          TYPES[t.name] = { name = t.name, check = t.check, params = type(t.params) == "table" and t.params or {},
                            text = crc(tostring(t.text or "")), ready = t.ready ~= false }
        end
      end
      for _, l in ipairs(root.PachangaTechniqueList or {}) do
        if type(l.name) == "string" then
          local set = LISTS[l.name] or {}
          for _, s in ipairs(type(l.skills) == "table" and l.skills or {}) do
            local id = id_of(s)
            if id then set[id] = true end
          end
          LISTS[l.name] = set
        end
      end
      if type(root.PachangaLevel) == "table" then
        local l = root.PachangaLevel
        LEVEL = { scale = tostring(l.scale or "data"), min = math.floor(tonumber(l.min) or 1),
                  max = math.floor(tonumber(l.max) or 200), row_level = math.floor(tonumber(l.row_level) or 0) }
      end
      for _, z in ipairs(root.PachangaZone or {}) do
        if type(z.name) == "string" and type(z.node) == "string" and by_zone[z.name] == nil then
          local zone = { name = z.name, node = z.node, title = crc(tostring(z.title or "")),
                         stadium = crc(tostring(z.stadium or "")), pachangas = {} }
          ZONES[#ZONES + 1] = zone
          by_zone[z.name] = zone
          BY_NODE[z.node] = #ZONES
        end
      end
      for _, p in ipairs(root.Pachanga or {}) do
        pending[#pending + 1] = { file = file, p = p }
      end
    end
  end
  for _, item in ipairs(pending) do
    local file, p = item.file, item.p
    local zone = by_zone[p.zone]
    if zone == nil or type(p.name) ~= "string" or type(p.team) ~= "string" then
      warn(string.format("mods/%s/%s: pachanga %s: unknown zone %s or no team: left out", tostring(file.mod),
        tostring(file.file), tostring(p.name), tostring(p.zone)))
    else
      local cards, challenges = {}, {}
      local given = type(p.challenges) == "table" and p.challenges or {}
      for i, c in ipairs(type(p.cards) == "table" and p.cards or {}) do
        local id = id_of(c)
        if id then
          cards[#cards + 1] = id
          local t = TYPES[tostring(given[i] or "")]
          challenges[#cards] = (t and t.ready) and t.name or ""
        end
      end
      local key = file.mod .. "." .. p.name
      local entry = { key = key, team = crc("evt_" .. p.team), team_name = tostring(p.team_name or p.name),
                      level = math.floor(tonumber(p.level) or 1), format = tostring(p.format or "5v5"),
                      level_offset = math.floor(tonumber(p.level_offset) or 0),
                      challenge = tostring(p.challenge or ""), cards = cards, challenges = challenges,
                      lineups = {} }
      -- the rotation's lineups (zone_rules.toml [lineup]): card indexes, 0-based in the data
      for _, lu in ipairs(type(p.lineups) == "table" and p.lineups or {}) do
        local l = {}
        for _, ix in ipairs(type(lu) == "table" and lu or {}) do
          local c = cards[math.floor(tonumber(ix) or -1) + 1]
          if c then l[#l + 1] = c end
        end
        if #l > 0 then entry.lineups[#entry.lineups + 1] = l end
      end
      if #entry.lineups == 0 then
        entry.lineups[1] = { table.unpack(cards, 1, math.min(5, #cards)) }
      end
      zone.pachangas[#zone.pachangas + 1] = entry
      BY_KEY[key] = entry
    end
  end
  local n = 0
  for _, z in ipairs(ZONES) do n = n + #z.pachangas end
  info(string.format("%d zone(s), %d pachanga(s)", #ZONES, n))
  return ZONES
end

local function plays_list(set)
  local out = {}
  for c in pairs(set) do out[#out + 1] = c end
  return out
end

-- the lineup of a pachanga's next match: its rotation turns at every entry (save key rot.<pachanga>)
local function lineup(p)
  local r = math.floor(tonumber(VRFW.save.get("rot." .. p.key, 0)) or 0)
  return p.lineups[(r % #p.lineups) + 1]
end

-- a pachanga's level now: the team level + its offset (scale "team", once the list gave the base), else its data level
local function level_of(p)
  local lv = p.level
  if LEVEL.scale == "team" and BASE ~= nil then
    lv = BASE + p.level_offset
  end
  return math.max(LEVEL.min, math.min(LEVEL.max, lv))
end

local function won(key)
  return VRFW.save.get("won." .. key, false) == true
end

local function met_before(card)
  return VRFW.save.get(string.format("met.%08X", card), false) == true
end

function P.Zone(node)
  load_zones()
  local i = BY_NODE[tostring(node)]
  local z = i and ZONES[i]
  if not z then return nil end
  return i, z.title, z.stadium, #z.pachangas
end

function P.Get(zi, i)
  local z = load_zones()[math.floor(tonumber(zi) or 0)]
  local p = z and z.pachangas[math.floor(tonumber(i) or 0)]
  if not p then return nil end
  return p.key, p.team, p.team_name, level_of(p), p.format, p.challenge, won(p.key), #p.cards, table.unpack(p.cards)
end

function P.Player(key, i)
  load_zones()
  local p = BY_KEY[tostring(key)]
  local card = p and p.cards[math.floor(tonumber(i) or 0)]
  if not card then return nil end
  local t = TYPES[p.challenges[math.floor(tonumber(i))] or ""]
  local first = t and (t.params.n or t.params.s) or 0
  return card, t and t.name or "", t and t.text or 0, first, met_before(card)
end

-- the pachanga list's page of the framework's pose row screen (content\pose_rows\pachangas.toml): i = 0 the header
-- (zone title, count), i >= 1 pachanga i (team, level, challenges met, each player's card and challenge text)
local TEXT = {
  COUNT = crc("new_recruitment_pachangas_count"), ROW = crc("new_recruitment_pachangas_row"),
  INFO = crc("new_recruitment_pachangas_info_5v5"), TAG = crc("new_recruitment_pachangas_tag_5v5"),
}
function P.Menu(zi, i)
  local z = load_zones()[math.floor(tonumber(zi) or 0)]
  if not z then return nil end
  i = math.floor(tonumber(i) or 0)
  if i == 0 then
    return { title = z.title, count = #z.pachangas, info = { id = TEXT.COUNT, args = { #z.pachangas } } }
  end
  local p = z.pachangas[i]
  if not p then return nil end
  -- every player: the next match's lineup first (page 1), then the others (the next pages)
  local idx, plays = {}, {}
  for k, card in ipairs(p.cards) do idx[card] = k end
  local order = {}
  for _, card in ipairs(lineup(p)) do
    if idx[card] then
      order[#order + 1] = idx[card]
      plays[card] = true
    end
  end
  for k, card in ipairs(p.cards) do
    if not plays[card] then order[#order + 1] = k end
  end
  local models, met = {}, 0
  for n, k in ipairs(order) do
    local card = p.cards[k]
    local t = TYPES[p.challenges[k] or ""]
    local done = met_before(card)
    if done then met = met + 1 end
    models[n] = { card = card, done = done, plays = plays[card] == true,
                  text = t and { id = t.text, vars = t.params } or "" }
  end
  local lv = level_of(p)
  return { label = p.team_name, title = p.team_name, tag = TEXT.TAG, level = lv, done = won(p.key), team = p.team,
           sub = { id = TEXT.ROW, args = { lv, met, #p.cards } }, info = { id = TEXT.INFO, args = { lv } },
           lineup = #plays_list(plays), models = models }
end

-- ------------------------------------------------------------------------------------------------ the match
local function side_of(actor) return type(actor) == "table" and actor.side or nil end
local function card_of_actor(actor) return type(actor) == "table" and actor.card or nil end
local function clock(ev) return (type(ev.match) == "table" and tonumber(ev.match.clock)) or 0 end

local function card_info(card)
  if card == nil or VRFW.chara == nil or VRFW.chara.card == nil then return nil end
  local ok, c = pcall(VRFW.chara.card, card)
  return ok and type(c) == "table" and c or nil
end

local function in_list(name, skill)
  local l = LISTS[name]
  return skill ~= nil and l ~= nil and l[skill] == true
end

local function arm(p)
  LIVE = { key = p.key, level = level_of(p), armed = true, gf = 0, ga = 0, goals = {}, keeps = 0, owner = nil, prev_owner = nil,
           shot = nil, chain = false, duel = nil, players = {} }
  for i, card in ipairs(p.cards) do
    local t = TYPES[p.challenges[i] or ""]
    if t then
      local his = card_info(card)
      LIVE.players[#LIVE.players + 1] = { card = card, type = t, count = 0, met = false, failed = false,
                                          element = his and his.element or 0 }
    end
  end
end

function P.Arm(key)
  load_zones()
  local p = BY_KEY[tostring(key)]
  if p == nil then return false end
  arm(p)
  PLAYED = nil
  if #p.lineups > 1 then     -- the next entry plays the next lineup
    VRFW.save.set("rot." .. p.key, math.floor(tonumber(VRFW.save.get("rot." .. p.key, 0)) or 0) + 1)
  end
  info(string.format("armed %s: %d challenge(s)", p.key, #LIVE.players))
  return true
end

-- every player's check on one match moment `m` = { kind, … }
local CHECKS = {}

local function count_to(pl, n)
  pl.count = pl.count + 1
  if pl.count >= (n or 1) then pl.met = true end
end

function CHECKS.goals(pl, m) if m.kind == "goal_user" then count_to(pl, pl.type.params.n) end end
function CHECKS.goal_technique(pl, m) if m.kind == "goal_user" and m.shot_skill then pl.met = true end end
function CHECKS.goal_own_element(pl, m)
  if m.kind == "goal_user" and m.shot_skill and m.scorer_element and in_list("element_" .. m.scorer_element, m.shot_skill) then pl.met = true end
end
function CHECKS.goal_chain(pl, m) if m.kind == "goal_user" and m.chain then pl.met = true end end
function CHECKS.goal_technique_in(pl, m)
  if m.kind == "goal_user" and in_list(tostring(pl.type.params.list or ""), m.shot_skill) then pl.met = true end
end
function CHECKS.goal_late(pl, m)
  local period = tonumber(pl.type.params.period) or 900
  if m.kind == "goal_user" and m.clock >= period - (tonumber(pl.type.params.s) or 30) then pl.met = true end
end
function CHECKS.goals_within(pl, m)
  if m.kind ~= "goal_user" then return end
  local n, s, g = tonumber(pl.type.params.n) or 2, tonumber(pl.type.params.s) or 60, LIVE.goals
  if #g >= n and g[#g] - g[#g - n + 1] <= s then pl.met = true end
end
function CHECKS.duel_him(pl, m)
  if m.kind ~= "duel" or m.loser ~= pl.card or m.winner_side ~= "user" then return end
  local want_kind, want_side = tostring(pl.type.params.kind or ""), tostring(pl.type.params.side or "")
  if want_kind ~= "" and m.duel_kind ~= want_kind then return end
  if want_side == "defense" and not m.block then return end
  if want_side == "offense" and m.block then return end
  count_to(pl, pl.type.params.n)
end
function CHECKS.goal_on_keeper(pl, m) if m.kind == "goal_user" and m.beaten_keeper == pl.card then pl.met = true end end
function CHECKS.he_scores_none(pl, m)
  if m.kind == "goal_rival" and m.scorer == pl.card then pl.failed = true end
  if m.kind == "end" and not pl.failed then pl.met = true end
end
function CHECKS.assist(pl, m) if m.kind == "goal_user" and m.assisted then pl.met = true end end
function CHECKS.passes(pl, m) if m.kind == "pass_user" then count_to(pl, pl.type.params.n) end end
function CHECKS.goal_after_passes(pl, m)
  if m.kind == "goal_user" and m.keeps >= (tonumber(pl.type.params.n) or 3) then pl.met = true end
end
function CHECKS.goal_by_position(pl, m)
  if m.kind ~= "goal_user" or not m.scorer_position then return end
  for _, pos in ipairs(type(pl.type.params.positions) == "table" and pl.type.params.positions or {}) do
    if pos == m.scorer_position then pl.met = true end
  end
end
function CHECKS.clean_sheet(pl, m) if m.kind == "end" and LIVE.ga == 0 then pl.met = true end end
function CHECKS.keeper_saves(pl, m) if m.kind == "save_user" and m.shot_skill then count_to(pl, pl.type.params.n) end end
function CHECKS.save_his_shot(pl, m)
  if m.kind == "save_user" and m.shot_skill and m.keeper_skill and m.shooter == pl.card then pl.met = true end
end
function CHECKS.technique_blocks(pl, m)
  if m.kind == "duel" and m.block and m.winner_side == "user" and m.duel_kind == "move" then count_to(pl, pl.type.params.n) end
end
function CHECKS.win_by(pl, m) if m.kind == "end" and LIVE.gf - LIVE.ga == (tonumber(pl.type.params.n) or 1) then pl.met = true end end
function CHECKS.move_element(pl, m)
  if m.kind == "move_user" and pl.element > 0 and in_list("element_" .. pl.element, m.skill) then pl.met = true end
end

local flush_duel

local function moment(m)
  if not LIVE or LIVE.armed then return end
  if m.kind ~= "duel" and LIVE.duel ~= nil then flush_duel() end
  for _, pl in ipairs(LIVE.players) do
    if not pl.met then
      local f = CHECKS[pl.type.check]
      if f then
        local ok, why = pcall(f, pl, m)
        if not ok then warn("check " .. pl.type.name .. ": " .. tostring(why)) end
      end
    end
  end
end

VRFW.on("match_start", function(ev)
  if LIVE and LIVE.armed then
    LIVE.armed = false
  elseif LIVE then
    LIVE = nil                                     -- another match: the armed pachanga was not played
  end
  return nil
end)

VRFW.on("possession", function(ev)
  if not LIVE or LIVE.armed then return nil end
  local card, side = card_of_actor(ev.actor), side_of(ev.actor)
  if ev.arg == "keep" and side == "user" then
    LIVE.keeps = LIVE.keeps + 1
    moment({ kind = "pass_user" })
  elseif ev.arg == "change" then
    LIVE.keeps = 0
  end
  LIVE.prev_owner, LIVE.owner = LIVE.owner, { card = card, side = side, clock = clock(ev) }
  return nil
end)

VRFW.on("chain_window_start", function(ev) if LIVE then LIVE.chain = ev.arg == "user" end return nil end)
VRFW.on("chain_window_end", function(ev) if LIVE then LIVE.chain_open = false end return nil end)

VRFW.on("shot_start", function(ev)
  if not LIVE or LIVE.armed then return nil end
  local owner = LIVE.owner or {}
  LIVE.shot = { skill = (ev.skill ~= nil and ev.skill ~= 0) and ev.skill or nil, shooter = owner.card,
                side = owner.side, chain = LIVE.chain == true, clock = clock(ev) }
  LIVE.chain = false
  return nil
end)

VRFW.on("move_power", function(ev)
  if LIVE and not LIVE.armed and side_of(ev.actor) == "user" then moment({ kind = "move_user", skill = ev.skill }) end
  return nil
end)

-- a focus duel's result comes as duel_won + duel_lost (+ block_won when the defense won), in any order: it is gathered
-- and counted once, at the next other match moment (or the next duel, or the match end)
flush_duel = function()
  local d = LIVE and LIVE.duel
  if d == nil then return end
  LIVE.duel = nil
  if d.winner and d.loser then moment(d) end
end

local function duel_part(ev, role)
  if not LIVE or LIVE.armed then return end
  local d = LIVE.duel
  if d ~= nil and d[role .. "_seen"] then
    flush_duel()
    d = nil
  end
  if d == nil then
    d = { kind = "duel", duel_kind = ev.arg }
    LIVE.duel = d
  end
  d[role .. "_seen"] = true
  if role == "winner" then d.winner, d.winner_side = card_of_actor(ev.actor), side_of(ev.actor) end
  if role == "loser" then d.loser = card_of_actor(ev.actor) end
  if role == "block" then d.block = true end
end
VRFW.on("duel_won", function(ev) duel_part(ev, "winner") return nil end)
VRFW.on("duel_lost", function(ev) duel_part(ev, "loser") return nil end)
VRFW.on("block_won", function(ev) duel_part(ev, "block") return nil end)

VRFW.on("keeper_save", function(ev)
  if not LIVE or LIVE.armed then return nil end
  local shot = LIVE.shot or {}
  if side_of(ev.actor) == "user" then
    moment({ kind = "save_user", shot_skill = shot.skill, shooter = shot.shooter,
             keeper_skill = (ev.skill ~= nil and ev.skill ~= 0) and ev.skill or nil })
  end
  return nil
end)

VRFW.on("keeper_beaten", function(ev)
  if LIVE and not LIVE.armed and LIVE.shot then LIVE.shot.beaten = card_of_actor(ev.actor) end
  return nil
end)

VRFW.on("goal", function(ev)
  if not LIVE or LIVE.armed then return nil end
  local m = type(ev.match) == "table" and ev.match or {}
  local s0, s1 = (m.score or {})[1], (m.score or {})[2]
  if s0 ~= nil and s1 ~= nil and m.user_team ~= nil then
    if m.user_team == 1 then LIVE.gf, LIVE.ga = s1, s0 else LIVE.gf, LIVE.ga = s0, s1 end
  end
  local scorer, shot = card_of_actor(ev.actor), LIVE.shot or {}
  if ev.arg == "user" then
    LIVE.goals[#LIVE.goals + 1] = clock(ev)
    local c = card_info(scorer)
    local prev = LIVE.prev_owner
    moment({ kind = "goal_user", scorer = scorer, clock = clock(ev), shot_skill = shot.skill, chain = shot.chain,
             beaten_keeper = shot.beaten, keeps = LIVE.keeps, scorer_element = c and c.element or nil,
             scorer_position = c and c.position or nil,
             assisted = prev ~= nil and prev.side == "user" and prev.card ~= scorer and
                        clock(ev) - (LIVE.owner and LIVE.owner.clock or 0) <= 8 })
  else
    moment({ kind = "goal_rival", scorer = scorer, clock = clock(ev) })
  end
  LIVE.shot, LIVE.keeps = nil, 0
  return nil
end)

-- the game's judge of a finished match onto a pachanga's record: won and the score (the goal events' count stays for
-- the challenges)
local function judge(record, result)
  record.won = result.outcome == "win"
  record.gf = tonumber(result.score_for) or record.gf
  record.ga = tonumber(result.score_against) or record.ga
  record.judged = true
end

-- the game's own result (VRFW MatchResult.last), published before or after match_end: onto the running pachanga, or
-- onto the one just played when match_end came first
VRFW.on("signal:vrfw.match_result", function()
  local results = rawget(_G, "MatchResult")
  local last = type(results) == "table" and results.last or nil
  if type(last) ~= "table" then return nil end
  if LIVE and not LIVE.armed then
    LIVE.result = last
  elseif PLAYED and not PLAYED.judged then
    judge(PLAYED, last)
    info(string.format("%s judged: %s %d-%d", PLAYED.key, tostring(last.outcome), PLAYED.gf, PLAYED.ga))
  end
  return nil
end)

VRFW.on("match_end", function(ev)
  if not LIVE or LIVE.armed then return nil end
  moment({ kind = "end" })
  local met = {}
  for _, pl in ipairs(LIVE.players) do
    if pl.met then met[#met + 1] = pl.card end
  end
  PLAYED = { key = LIVE.key, level = LIVE.level, gf = LIVE.gf, ga = LIVE.ga, won = false, met = met, judged = false }
  if LIVE.result then judge(PLAYED, LIVE.result) end
  info(string.format("%s over: %d-%d, %d challenge(s) met%s", LIVE.key, PLAYED.gf, PLAYED.ga, #met,
    PLAYED.judged and "" or " (the game's result not seen yet)"))
  LIVE = nil
  return nil
end)

function P.Result()
  local r = PLAYED
  PLAYED = nil
  if not r then return nil end
  local p = BY_KEY[r.key]
  return r.key, r.won, r.gf, r.ga, r.level or level_of(p), #r.met, table.unpack(r.met)
end

function P.Won(key) return won(tostring(key)) end

function P.Base(level)
  load_zones()
  local lv = math.floor(tonumber(level) or 0)
  BASE = lv >= 1 and lv or nil
  return true
end

function P.Level(key)
  load_zones()
  local p = BY_KEY[tostring(key)]
  if not p then return nil end
  return level_of(p), LEVEL.row_level
end

function P.Lineup(key)
  load_zones()
  local p = BY_KEY[tostring(key)]
  if not p then return nil end
  return table.unpack(lineup(p))
end

function P.SetWon(key)
  VRFW.save.set("won." .. tostring(key), true)
  return true
end

function P.SetMet(card)
  VRFW.save.set(string.format("met.%08X", math.floor(tonumber(card) or 0) % 4294967296), true)
  return true
end

-- the commands (content\game\pachangas.toml)
NewRecruitment.PachangaZone = P.Zone
NewRecruitment.PachangaGet = P.Get
NewRecruitment.PachangaPlayer = P.Player
NewRecruitment.PachangaArm = P.Arm
NewRecruitment.PachangaResult = P.Result
NewRecruitment.PachangaWon = P.Won
NewRecruitment.PachangaSetWon = P.SetWon
NewRecruitment.PachangaSetMet = P.SetMet
NewRecruitment.PachangaMenu = P.Menu
NewRecruitment.PachangaLineup = P.Lineup
NewRecruitment.PachangaBase = P.Base
NewRecruitment.PachangaLevel = P.Level

pcall(load_zones)
